(()=>{const root=document.querySelector('#product-detail');const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(v/100);const wa=(phone,name)=>`https://wa.me/${phone}?text=${encodeURIComponent(`Olá! Gostaria de informações sobre o produto ${name}.`)}`;const query=new URLSearchParams(location.search);const id=query.get('id');const descriptionMarkup=(p,photos)=>{const blocks=Array.isArray(p.descriptionBlocks)?p.descriptionBlocks.filter(b=>b&&(b.text||b.image)):[];if(Array.isArray(p.descriptionBlocks))return blocks.map((b,i)=>{const layout=['text-image','image-text','text','image'].includes(b.layout)?b.layout:'text-image';return`<article class="description-block ${layout}">${b.text?`<div class="description-block-text"><p>${esc(b.text)}</p></div>`:''}${b.image?`<div class="description-block-image"><img src="${esc(b.image)}" alt="${esc(p.name)} — imagem ${i+1}"></div>`:''}</article>`}).join('');return`${p.longDescription||p.description?`<article class="description-block text"><div class="description-block-text"><p>${esc(p.longDescription||p.description)}</p></div></article>`:''}${photos.map((src,i)=>`<article class="description-block image"><div class="description-block-image"><img src="${esc(src)}" alt="${esc(p.name)} — imagem ${i+1}"></div></article>`).join('')}`};fetch('/api/catalog',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error();return r.json()}).then(async store=>{const p=store.products.find(x=>x.id===id);if(!p){root.innerHTML='<div class="empty"><h1>Produto não encontrado</h1><p>Confira o catálogo para ver os produtos disponíveis.</p><a class="button primary" href="produtos.html">Ver produtos</a></div>';return}try{const reviewResponse=await fetch('/api/product-reviews?id='+encodeURIComponent(p.id),{cache:'no-store'});if(!reviewResponse.ok)throw Error();p.reviews=(await reviewResponse.json()).reviews}catch{p.reviews=[];p.reviewsUnavailable=true}document.title=p.name+' | '+store.settings.name;document.querySelectorAll('.brand-logo').forEach(img=>{img.src=store.settings.logo;img.alt=store.settings.name});document.querySelector('link[rel="icon"]').href=store.settings.favicon;document.querySelector('.topbar a').href=wa(store.settings.phone,p.name);const photos=(p.images?.length?p.images:(p.image?[p.image]:[]));const gallery=photos.length?`<div class="detail-gallery"><div class="detail-main-image"><img id="detail-main-image" src="${esc(photos[0])}" alt="${esc(p.name)}"></div><div class="detail-thumbs">${photos.map((src,i)=>`<button type="button" class="detail-thumb ${i===0?'active':''}" data-photo="${esc(src)}"><img src="${esc(src)}" alt="${esc(p.name)} — foto ${i+1}"></button>`).join('')}</div></div>`:`<div class="detail-gallery detail-placeholder"><span>Sem foto cadastrada</span></div>`;const specs=(p.specs||[]).length?`<section class="detail-section"><div class="eyebrow">INFORMAÇÕES TÉCNICAS</div><h2>Ficha técnica</h2><div class="spec-table">${p.specs.map(s=>`<div><strong>${esc(s.label)}</strong><span>${esc(s.value)}</span></div>`).join('')}</div></section>`:'';const reviews=(p.reviews||[]).length?`<section class="detail-section"><div class="eyebrow">AVALIAÇÕES DO PRODUTO</div><h2>Avaliações do produto</h2><div class="product-reviews">${p.reviews.map(r=>`<article><div class="review-stars" aria-label="${r.rating} estrelas">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</div><p>“${esc(r.text)}”</p><strong>${esc(r.name)}${r.demo?' · Avaliação de demonstração':r.verified?' · Compra verificada':''}</strong></article>`).join('')}</div></section>`:`<section class="detail-section"><div class="eyebrow">AVALIAÇÕES</div><h2>${p.reviewsUnavailable?'Avaliações indisponíveis no momento.':'Ainda não há avaliações deste produto.'}</h2><p class="muted">As avaliações são publicadas por clientes com compras concluídas. <a href="membros.html">Entre na sua conta para avaliar.</a></p></section>`;const price=p.price===null?'Sob consulta':money(p.price);const action=p.mode==='cart'?`<a class="button primary full" href="membros.html?checkout=1" data-buy-product>Comprar produto</a>`:`<a class="button primary full" href="${wa(store.settings.phone,p.name)}" target="_blank" rel="noopener noreferrer">Consultar pelo WhatsApp</a>`;root.innerHTML=`<nav class="breadcrumbs" aria-label="Você está aqui"><a href="produtos.html">Produtos</a><span>/</span><span>${esc(p.name)}</span></nav><section class="detail-hero">${gallery}<div class="detail-summary"><div class="product-category">${esc(p.category)}</div><h1>${esc(p.name)}</h1><p class="detail-description">${esc(p.description)}</p><div class="detail-price">${price}</div><p class="price-note">${store.settings.demo?'Valor ilustrativo • confirme estoque e condições':'Consulte condições e disponibilidade'}</p><div class="payment-box"><strong>Pagamento e entrega</strong><p>${esc(p.paymentInfo||'Pagamento online em preparação. Confirme disponibilidade, prazo e forma de pagamento pelo WhatsApp.')}</p></div>${action}</div></section><section class="detail-section description-section"><div class="description-heading"><div class="eyebrow">SOBRE O PRODUTO</div><h2>Detalhes e descrição</h2></div><div class="description-blocks">${descriptionMarkup(p,p.detailImages?.length?p.detailImages:photos)}</div></section>${specs}${reviews}`;document.querySelector('[data-buy-product]')?.addEventListener('click',()=>{let items=[];try{items=JSON.parse(sessionStorage.getItem('sos-cart')||'[]')}catch{}const cart=new Map(Array.isArray(items)?items:[]);cart.set(p.id,Math.min(10,(cart.get(p.id)||0)+1));sessionStorage.setItem('sos-cart',JSON.stringify([...cart]));sessionStorage.removeItem('sos-order-request')});document.querySelectorAll('[data-photo]').forEach(btn=>btn.onclick=()=>{document.querySelector('#detail-main-image').src=btn.dataset.photo;document.querySelectorAll('.detail-thumb').forEach(x=>x.classList.toggle('active',x===btn))});document.querySelector('#year').textContent=new Date().getFullYear()}).catch(()=>{root.innerHTML='<div class="empty"><h1>Não foi possível carregar este produto.</h1><a class="button primary" href="produtos.html">Voltar ao catálogo</a></div>'})})();
(()=>{const id=new URLSearchParams(location.search).get('id');if(!id)return;fetch('/api/catalog',{cache:'no-store'}).then(r=>r.json()).then(store=>{const p=store.products.find(x=>x.id===id);if(!p)return;const fields=[['Marca',p.brand],['Modelo',p.model],['SKU',p.sku]].filter(([,value])=>value);if(!fields.length)return;const insert=()=>{const summary=document.querySelector('.detail-summary');if(!summary||summary.querySelector('.product-meta'))return false;const box=document.createElement('div');box.className='product-meta';box.innerHTML=fields.map(([label,value])=>`<div><span>${label}</span><strong>${String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}</strong></div>`).join('');const price=summary.querySelector('.detail-price');summary.insertBefore(box,price||summary.firstChild);return true};if(!insert()){const observer=new MutationObserver(()=>{if(insert())observer.disconnect()});observer.observe(document.querySelector('#product-detail'),{childList:true,subtree:true})}}).catch(()=>{})})();
(()=>{const key='sos-theme';const saved=localStorage.getItem(key);if(saved==='dark'||saved==='light')document.documentElement.dataset.theme=saved;const header=document.querySelector('.header-inner');if(!header||header.querySelector('.theme-toggle'))return;const button=document.createElement('button');button.type='button';button.className='theme-toggle';button.setAttribute('aria-label','Ativar modo noturno');button.innerHTML='<span aria-hidden="true">☾</span><span class="theme-toggle-label">Modo noturno</span>';const update=()=>{const dark=document.documentElement.dataset.theme==='dark';button.setAttribute('aria-label',dark?'Ativar modo claro':'Ativar modo noturno');button.innerHTML=dark?'<span aria-hidden="true">☀</span><span class="theme-toggle-label">Modo claro</span>':'<span aria-hidden="true">☾</span><span class="theme-toggle-label">Modo noturno</span>'};button.onclick=()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem(key,next);update()};header.append(button);update()})();
